CREATE UNIQUE INDEX library_items_id_owner ON library_items(id,user_id);
CREATE TABLE attachments(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),resource_id TEXT,filename TEXT NOT NULL CHECK(length(filename) BETWEEN 1 AND 255),mime TEXT NOT NULL CHECK(mime IN ('application/pdf','image/png','image/jpeg','image/webp','text/plain')),byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 26214400),sha256 TEXT NOT NULL CHECK(length(sha256)=64),FOREIGN KEY(resource_id,user_id) REFERENCES library_items(id,user_id) ON DELETE RESTRICT);
CREATE INDEX attachments_parent ON attachments(resource_id,user_id);
CREATE TRIGGER sync_attachments_insert AFTER INSERT ON attachments WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('attachments',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'resource_id',NEW.resource_id,'filename',NEW.filename,'mime',NEW.mime,'byte_size',NEW.byte_size,'sha256',NEW.sha256),(SELECT revision FROM native_sync_meta WHERE entity_table='attachments' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='attachments' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_attachments_update AFTER UPDATE ON attachments WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('attachments',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'resource_id',NEW.resource_id,'filename',NEW.filename,'mime',NEW.mime,'byte_size',NEW.byte_size,'sha256',NEW.sha256),(SELECT revision FROM native_sync_meta WHERE entity_table='attachments' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='attachments' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_attachments_delete AFTER DELETE ON attachments WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('attachments',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='attachments' AND id=OLD.id),OLD.remote_updated_at); END;
